218:             ResultSetMetaData rsmd = rs.getMetaData();
219:             int numberOfColumns = rsmd.getColumnCount();
220:             out.write("Your results are:<br>\n");
221: 
222:             while (rs.next()) {
223:                 for (int i = 1; i <= numberOfColumns; i++) {
224:                     if (i > 1) {
